CREATE TABLE IF NOT EXISTS "ALUMNOS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "RUN" VARCHAR(20) NOT NULL UNIQUE,
    "NOMBRE" VARCHAR(120) NOT NULL,
    "APELLIDOS" VARCHAR(120) NOT NULL,
    "DIRECCION" VARCHAR(250),
    "FECHA_NACIMIENTO" DATE NOT NULL,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE
);

CREATE TABLE IF NOT EXISTS "CURSO_ALUMNOS" (
    "ID" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "CURSO_ID" BIGINT NOT NULL,
    "ALUMNO_ID" BIGINT NOT NULL UNIQUE,
    "FECHA_ASIGNACION" DATE NOT NULL DEFAULT CURRENT_DATE,
    "ACTIVO" BOOLEAN NOT NULL DEFAULT TRUE,
    CONSTRAINT "FK_CURSO_ALUMNOS_CURSOS" FOREIGN KEY ("CURSO_ID") REFERENCES "CURSOS" ("ID"),
    CONSTRAINT "FK_CURSO_ALUMNOS_ALUMNOS" FOREIGN KEY ("ALUMNO_ID") REFERENCES "ALUMNOS" ("ID")
);

