INSERT INTO "CURSO_ALUMNOS" ("CURSO_ID", "ALUMNO_ID", "ACTIVO")
SELECT c."ID", a."ID", TRUE
FROM "CURSOS" c
JOIN "ALUMNOS" a ON a."RUN" IN ('10.100.100-4', '10.100.100-8')
WHERE c."CODIGO" = '5B-2026'
  AND NOT EXISTS (
      SELECT 1 FROM "CURSO_ALUMNOS" ca WHERE ca."ALUMNO_ID" = a."ID"
  );
